DROP TEMPORARY TABLE IF EXISTS `tmp_fix_page_text_Text`;
CREATE TEMPORARY TABLE `tmp_fix_page_text_Text` (`ID` VARCHAR(32) NOT NULL, `txt` TEXT NOT NULL, PRIMARY KEY (`ID`)) DEFAULT CHARSET=utf8mb4;
UPDATE `page_text` t JOIN `tmp_fix_page_text_Text` f ON f.`ID` = t.`ID` SET t.`Text` = f.`txt` WHERE t.`Text` REGEXP "(Ð|Ñ|Ã)[^ a-zA-Z0-9].*(Ð|Ñ|Ã)[^ a-zA-Z0-9]";
DROP TEMPORARY TABLE `tmp_fix_page_text_Text`;
