DELETE t2 FROM `creature_text` t JOIN `creature_text` t2 ON t2.`CreatureID` = t.`CreatureID` AND t2.`GroupID` = t.`GroupID` AND t2.`ID` = t.`ID` AND t2.`BroadcastTextID` = t.`BroadcastTextID` AND t2.`Text` > t.`Text` JOIN `tmp_fix_creature_text` f ON f.`CreatureID` = t.`CreatureID` AND f.`GroupID` = t.`GroupID` AND f.`ID` = t.`ID` AND f.`BroadcastTextID` = t.`BroadcastTextID` WHERE t.`Text` REGEXP "(Ð|Ñ|Ã)[^ a-zA-Z0-9].*(Ð|Ñ|Ã)[^ a-zA-Z0-9]|(Ã|Â)[¡¢£¤¥¦§¨©ª«¬­®¯°±²³´µ¶·¸¹º»¼½¾¿€‚ƒ„…†‡ˆ‰Š‹ŒŽ‘’“”•–—˜™š›œžŸ]|â€" AND t2.`Text` REGEXP "(Ð|Ñ|Ã)[^ a-zA-Z0-9].*(Ð|Ñ|Ã)[^ a-zA-Z0-9]|(Ã|Â)[¡¢£¤¥¦§¨©ª«¬­®¯°±²³´µ¶·¸¹º»¼½¾¿€‚ƒ„…†‡ˆ‰Š‹ŒŽ‘’“”•–—˜™š›œžŸ]|â€";
