(77795, 4, 0, 80550, 'NO! Noooooooooooooooooooooooooooooooo!'),
(77795, 4, 0, 80549, 'My power... it fades!'),
(77799, 3, 0, 83782, 'Deliver us from the darkness and shine your light upon us.'),
(77799, 3, 0, 83783, 'Hide us from the Dark One. Protect our people from the Great Shadow.'),
(77799, 3, 0, 83781, 'Light of Lights, cover us from those who wish us harm.'),
(77799, 3, 0, 83784, 'We are the children of the Light. We ask for naught but peace.'),
(77803, 4, 0, 89110, 'Rocketspark leaps, beginning a |TInterface\\Icons\\inv_misc_missilelargecluster_red.blp:20|t |cFFFF0404|Hspell:162407|h[X21-01A Missile Barrage]|h|r!'),
(77803, 4, 0, 83798, 'You big oaf! Quit breaking my things!'),
