(93841, 3, 0, 100323, 'Skyhorn! Take to the air and show these harpies and their rocs the meaning of battle!'),
(93841, 3, 0, 121326, 'I greet you, wielder of Talonclaw.'),
(93858, 0, 0, 95603, 'Reporting for duty!'),
(93858, 1, 0, 139449, 'Attack!'),
