(93890, 0, 0, 95512, 'Please find my nephew before he goes mad like the others!'),
(93892, 3, 0, 95517, 'I go to my uncle. Thank you, kind stranger!'),
(93913, 0, 0, 96142, '|TInterface\\Icons\\spell_fire_ragnaros_molteninferno.blp:20|tThe $n |cFFFF0000|Hspell:185824|h[Detonates]|h|r as it dies!'),
(93926, 0, 0, 95882, 'You have foolishly rushed to your end. The Black Gate is whole!'),
(93926, 1, 0, 95883, 'Behold the might of the legion!'),
