(107302, 4, 0, 113855, 'Grlmgrl, mgrlgrg. Glrgrlmrgl mrglrlgr lrglr! Rlmgrlm mgrglrmg mrglrglrm. Mrlgrgmrlg gmrlgrl mlrglrg?'),
(107302, 5, 0, 113856, 'Mrg, mrlgmrlg...'),
(107302, 6, 0, 114794, 'Glmrg! Gmlrgm mglrmgrl mrmglr!'),
(107315, 3, 0, 121033, 'As with those that came before me, I pledge my service to you and the Unseen Path.'),
(107316, 0, 0, 120512, 'If you are leading the order in its efforts to help those in need, then I offer myself to aid in any way I can.'),
(107317, 0, 0, 121038, 'I pledge my loyalty to you, and to the Unseen Path, for all my days.'),
(107318, 0, 0, 115406, 'Keep it down, brats. You will join the others soon.'),
(107318, 1, 0, 111601, 'Stop following me!'),
(107324, 3, 0, 121053, 'Run! They have weapons!'),
(107324, 3, 0, 121049, 'Outsiders!'),
(107327, 1, 0, 123254, 'Yes... your brain will do nicely... give it to me!'),
(107333, 0, 0, 115553, 'Intruder! Face my blade!'),
(107333, 1, 0, 115554, 'She sealed her fate, as you have sealed yours!'),
